"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[98143],{95830:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"GunHandler","desc":"Category handler for hitscan guns. Predicts fire-rate and ammo for snappy\\nfeel, draws the shooter\'s tracer/muzzle FX, and sends `ReqFireWeapon` for the\\nserver to apply authoritative damage. Supports semi and automatic fire (held\\nvia OnActivate/OnDeactivate) and reload (OnReload). Local ammo is predicted\\nvia AmmoApi and reconciled by the server\'s `WeaponMagSync`/`AmmoPoolSync`.\\nSpread is a live cone (base `Spread` after the perk + firing bloom + movement\\nbloom, `CrosshairMath`); the equipped gun publishes it as the crosshair source\\nso the crosshair shows exactly the cone each shot rolls in.\\nNo shot while sprinting, nor until the gun is back up from the sprint lower\\n(`WeaponFeelConfig.SprintFireReady`); the server rejects those shots too. Each\\nshot kicks the gun (`WeaponFeel.KickModel`) and the camera (`RequestCameraKick`:\\nthe aim climbs and recovers).","realm":["Client"],"source":{"line":19,"path":"src/StarterPlayer/StarterPlayerScripts/WeaponHandlers/GunHandler.luau"}}')}}]);